import { expect, test, uniqueName } from "../../fixtures";

/** Builds a small, valid single-page PDF whose text layer contains the given lines. */
function buildPdf(lines: string[]): Buffer {
  const escape = (s: string) => s.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
  const textOps = lines.map((l) => `(${escape(l)}) Tj T*`).join("\n");
  const stream = `BT\n/F1 12 Tf\n14 TL\n72 720 Td\n${textOps}\nET`;

  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
    `<< /Length ${Buffer.byteLength(stream, "latin1")} >>\nstream\n${stream}\nendstream`,
  ];

  let pdf = "%PDF-1.4\n";
  const offsets: number[] = [];
  objects.forEach((body, i) => {
    offsets.push(Buffer.byteLength(pdf, "latin1"));
    pdf += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xrefOffset = Buffer.byteLength(pdf, "latin1");
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  for (const off of offsets) {
    pdf += `${off.toString().padStart(10, "0")} 00000 n \n`;
  }
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`;
  return Buffer.from(pdf, "latin1");
}

test.describe("Upload vendor documents", () => {
  test(
    "fields that cannot be parsed get low confidence",
    { tag: "@DOC-03" },
    async ({ apiAs }) => {
      test.setTimeout(90_000);

      // Background: signed in as member, a vendor in status draft
      const member = await apiAs("member");
      const vendorName = uniqueName("DOC-03 Vendor");
      const createRes = await member.post("/api/vendors", {
        data: {
          name: vendorName,
          category: "services",
          contact_email: `doc03-${Date.now()}@example.com`,
        },
      });
      expect(createRes.status()).toBe(201);
      const vendor = await createRes.json();
      expect(vendor.status).toBe("draft");

      // Given I uploaded an insurance certificate whose expiry date is "next spring"
      const pdf = buildPdf([
        "CERTIFICATE OF LIABILITY INSURANCE",
        `Insured: ${vendorName}`,
        "Insurer: Acme Mutual Insurance Co.",
        "Policy Number: POL-1234567",
        "Coverage Amount: $1,000,000",
        "Effective Date: 2024-01-01",
        "Expiry Date: next spring",
      ]);
      const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance-certificate-doc03.pdf",
            mimeType: "application/pdf",
            buffer: pdf,
          },
        },
      });
      expect(uploadRes.status()).toBe(201);
      const document = await uploadRes.json();
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.kind).toBe("insurance_certificate");

      // When processing finishes
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${document.id}`);
            expect(res.status()).toBe(200);
            return (await res.json()).status;
          },
          { timeout: 60_000, intervals: [250, 500, 1000] },
        )
        .not.toBe("processing");

      const finalDoc = await (await member.get(`/api/documents/${document.id}`)).json();
      expect(finalDoc.status).toBe("extracted");

      // Then the "expiry_date" field has a null value and confidence below 0.5
      const extractionRes = await member.get(`/api/documents/${document.id}/extraction`);
      expect(extractionRes.status()).toBe(200);
      const extraction = await extractionRes.json();
      expect(extraction.document_id).toBe(document.id);
      expect(extraction.kind).toBe("insurance_certificate");
      expect(extraction.fields).toHaveProperty("expiry_date");

      const expiry = extraction.fields.expiry_date;
      expect(expiry.value).toBeNull();
      expect(typeof expiry.confidence).toBe("number");
      expect(expiry.confidence).toBeLessThan(0.5);
    },
  );
});
